CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, draft TEXT NOT NULL, published TEXT, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, csrf TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS quick_msgs (id TEXT PRIMARY KEY, sec TEXT NOT NULL DEFAULT '', grp TEXT NOT NULL DEFAULT '', title TEXT NOT NULL, body TEXT NOT NULL, created TEXT NOT NULL, updated TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS quick_photos (id TEXT PRIMARY KEY, sec TEXT NOT NULL DEFAULT '', grp TEXT NOT NULL DEFAULT '', album TEXT NOT NULL, label TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, created TEXT NOT NULL);
